mapper.select:
SELECT FROM automation_ui_execution e
WHERE e.scene_id = #{sceneDbId}
ORDER BY e.create_time DESC, e.id DESC LIMIT 1

SELECT 
FROM automation_ui_execution e

WHERE e.scene_id = #{query.sceneDbId}

AND e.status = #{query.status}
AND e.result = #{query.result}

ORDER BY e.create_time
ASCDESC,
         e.id
ASCDESC
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM automation_ui_execution e

WHERE e.scene_id = #{query.sceneDbId}

AND e.status = #{query.status}
AND e.result = #{query.result}

    AND


            (e.create_time > #{cursorTime} OR (e.create_time = #{cursorTime} AND e.id > #{cursorId}))


            (e.create_time < #{cursorTime} OR (e.create_time = #{cursorTime} AND e.id < #{cursorId}))




ORDER BY e.create_time
ASCDESC,
         e.id
ASCDESC
LIMIT #{limit}

SELECT s.id AS scene_db_id, e.id AS execution_db_id, COALESCE(es.execution_revision, 0) AS global_execution_revision, COUNT(c.id) AS total FROM automation_ui_execution e
LEFT JOIN automation_ui_scene_execution_state es ON es.scene_id = s.id LEFT JOIN automation_ui_execution_case c ON c.execution_id = e.id WHERE e.id = #{executionDbId}
GROUP BY s.id, e.id, es.execution_revision

SELECT 
FROM automation_ui_execution_case c
JOIN automation_ui_execution e ON e.id = c.execution_id

WHERE e.id = #{executionDbId}

ORDER BY c.case_index, c.attempt_no, c.id
LIMIT #{limit} OFFSET #{offset}

SELECT s.id AS scene_db_id, COALESCE(es.execution_revision, 0) AS global_execution_revision, COUNT(c.id) AS total FROM automation_ui_execution e
LEFT JOIN automation_ui_scene_execution_state es ON es.scene_id = s.id LEFT JOIN automation_ui_execution_case c ON c.execution_id = e.id AND (c.case_id = #{query.caseId} OR c.case_key = #{query.caseId}) WHERE e.scene_id = #{query.sceneDbId}
GROUP BY s.id, es.execution_revision

SELECT , e.execution_key, e.batch_id, s.id AS scene_db_id, e.scene_key, , e.test_plan_id, e.test_report_id, e.build_number, e.execution_engine, e.execute_username, e.execute_name, e.project_environment_id, e.project_environment_name FROM automation_ui_execution_case c JOIN automation_ui_execution e ON e.id = c.execution_id
WHERE e.scene_id = #{query.sceneDbId} AND (c.case_id = #{query.caseId} OR c.case_key = #{query.caseId})
ORDER BY COALESCE(c.started_at, c.create_time) DESC, c.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT s.id AS scene_db_id, e.id AS execution_db_id, c.id AS case_execution_db_id, COALESCE(es.execution_revision, 0) AS global_execution_revision, COUNT(st.id) AS total FROM automation_ui_execution_case c JOIN automation_ui_execution e ON e.id = c.execution_id
LEFT JOIN automation_ui_scene_execution_state es ON es.scene_id = s.id LEFT JOIN automation_ui_execution_step st ON st.execution_case_id = c.id WHERE c.id = #{caseExecutionDbId}
GROUP BY s.id, e.id, c.id, es.execution_revision

SELECT FROM automation_ui_execution_step st JOIN automation_ui_execution_case c ON c.id = st.execution_case_id JOIN automation_ui_execution e ON e.id = c.execution_id
WHERE c.id = #{caseExecutionDbId}
ORDER BY st.step_index, st.attempt_no, st.id LIMIT #{limit} OFFSET #{offset}

SELECT s.id AS scene_db_id, e.id AS execution_db_id, COALESCE(es.execution_revision, 0) AS global_execution_revision, COUNT(a.id) AS total FROM automation_ui_execution e
LEFT JOIN automation_ui_scene_execution_state es ON es.scene_id = s.id LEFT JOIN automation_ui_execution_artifact a ON a.execution_id = e.id WHERE e.id = #{executionDbId}
GROUP BY s.id, e.id, es.execution_revision

SELECT a.id AS artifact_db_id, a.execution_id AS execution_db_id, NULLIF(a.execution_case_id, 0) AS case_execution_db_id, NULLIF(a.execution_step_id, 0) AS step_execution_db_id, a.artifact_type, a.storage_status, a.size_bytes, a.expires_at, a.create_time, a.update_time FROM automation_ui_execution_artifact a JOIN automation_ui_execution e ON e.id = a.execution_id
WHERE e.id = #{executionDbId}
ORDER BY a.create_time DESC, a.id DESC LIMIT #{limit} OFFSET #{offset}
